SELECT typeof(capacity_slot) AS slot_class, CAST(capacity_slot AS TEXT) AS capacity_slot, item_id,record,stream,typeof(seq) AS seq_class,CAST(seq AS TEXT) AS seq,typeof(live) AS live_class,CAST(live AS TEXT) AS live,typeof(payload_bytes) AS payload_class,CAST(payload_bytes AS TEXT) AS payload_bytes,typeof(settlement_bytes) AS settlement_class,CAST(settlement_bytes AS TEXT) AS settlement_bytes FROM _fleet_sync_mail_items WHERE stream = ?1 AND seq > CAST(?2 AS INTEGER) ORDER BY _fleet_sync_mail_items.seq LIMIT CAST(?3 AS INTEGER);
